import React, { useState, useEffect } from 'react';
import { gql } from '@apollo/client';
import { useQuery, useMutation } from '@apollo/client/react';

const LOGIN_USER = gql`
  mutation Login($email: String!, $password: String!) {
    login(email: $email, password: $password) {
      id
      email
    }
  }
`;

const GET_TODOS = gql`
  query GetTodos($userId: ID!) {
    getTodos(userId: $userId) {
      id
      text
      completed
    }
  }
`;

const CREATE_TODO = gql`
  mutation CreateTodo($userId: ID!, $text: String!) {
    createTodo(userId: $userId, text: $text) {
      id
      text
      completed
    }
  }
`;

const DELETE_TODO = gql`
  mutation DeleteTodo($id: ID!) {
    deleteTodo(id: $id)
  }
`;

export default function App() {
  // Session Persistence
  const [user, setUser] = useState(() => {
    const saved = localStorage.getItem('todo_user');
    return saved ? JSON.parse(saved) : null;
  });

  // Dark Mode State
  const [darkMode, setDarkMode] = useState(() => {
    return localStorage.getItem('todo_theme') === 'dark';
  });

  const [email, setEmail] = useState('test@test.com');
  const [password, setPassword] = useState('password123');
  const [showPassword, setShowPassword] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [login] = useMutation(LOGIN_USER);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('todo_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('todo_theme', 'light');
    }
  }, [darkMode]);

  const handleLogin = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      setErrorMsg('');
      const { data } = await login({ variables: { email, password } });
      setUser(data.login);
      localStorage.setItem('todo_user', JSON.stringify(data.login));
    } catch (err) {
      setErrorMsg(err.message || 'Invalid credentials. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('todo_user');
  };

  if (!user) {
    return (
      <div className={`min-h-screen flex items-center justify-center p-4 transition-colors duration-200 ${darkMode ? 'bg-slate-900 text-slate-100' : 'bg-slate-50 text-slate-800'}`}>
        <div className={`max-w-md w-full rounded-2xl shadow-xl p-8 border transition-all ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-100'}`}>
          <div className="flex justify-between items-center mb-6">
            <span className="text-xs font-mono px-2.5 py-1 rounded-full bg-indigo-50 dark:bg-indigo-950 text-indigo-600 dark:text-indigo-400 font-medium">v1.0.0</span>
            <button
              onClick={() => setDarkMode(!darkMode)}
              className="p-2 rounded-xl text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-700 dark:text-slate-400 transition"
              title="Toggle Dark Mode"
            >
              {darkMode ? '☀️ Light' : '🌙 Dark'}
            </button>
          </div>

          <div className="text-center mb-8">
            <div className="inline-flex items-center justify-center w-12 h-12 bg-indigo-50 dark:bg-indigo-900/50 text-indigo-600 dark:text-indigo-400 rounded-xl mb-3 shadow-sm">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <h1 className="text-2xl font-bold tracking-tight">Welcome Back</h1>
            <p className="text-slate-500 dark:text-slate-400 text-sm mt-1">Sign in to access your task dashboard</p>
          </div>

          {errorMsg && (
            <div className="mb-5 p-3.5 bg-rose-50 dark:bg-rose-950/50 border border-rose-200 dark:border-rose-800 text-rose-600 dark:text-rose-400 text-xs rounded-xl flex items-center gap-2">
              <svg className="w-4 h-4 shrink-0" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
              </svg>
              <span>{errorMsg}</span>
            </div>
          )}

          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 mb-1.5">Email Address</label>
              <input 
                type="email" 
                value={email} 
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-2.5 border rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 focus:outline-none text-sm transition dark:bg-slate-700 dark:border-slate-600 dark:text-white border-slate-200 text-slate-700"
                required
              />
            </div>
            <div>
              <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 mb-1.5">Password</label>
              <div className="relative">
                <input 
                  type={showPassword ? "text" : "password"} 
                  value={password} 
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full px-4 py-2.5 pr-12 border rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 focus:outline-none text-sm transition dark:bg-slate-700 dark:border-slate-600 dark:text-white border-slate-200 text-slate-700"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-semibold text-slate-400 hover:text-indigo-600 transition p-1"
                >
                  {showPassword ? 'Hide' : 'Show'}
                </button>
              </div>
            </div>
            <button 
              type="submit"
              disabled={isSubmitting}
              className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 text-white font-semibold rounded-xl transition duration-200 shadow-md shadow-indigo-100 dark:shadow-none disabled:opacity-50 text-sm"
            >
              {isSubmitting ? 'Signing in...' : 'Sign In'}
            </button>
          </form>

          <div className="mt-6 pt-5 border-t border-slate-100 dark:border-slate-700 text-center text-xs text-slate-400">
            Demo Credentials: <span className="font-mono text-slate-600 dark:text-slate-300 bg-slate-100 dark:bg-slate-700 px-1.5 py-0.5 rounded">test@test.com</span> / <span className="font-mono text-slate-600 dark:text-slate-300 bg-slate-100 dark:bg-slate-700 px-1.5 py-0.5 rounded">password123</span>
          </div>
        </div>
      </div>
    );
  }

  return <TodoDashboard user={user} onLogout={handleLogout} darkMode={darkMode} setDarkMode={setDarkMode} />;
}

function TodoDashboard({ user, onLogout, darkMode, setDarkMode }) {
  const [taskText, setTaskText] = useState('');
  const [priority, setPriority] = useState('Medium');
  const [searchQuery, setSearchQuery] = useState('');
  const [filterTab, setFilterTab] = useState('all'); 
  const [sortBy, setSortBy] = useState('default'); // 'default', 'priority', 'alphabetical'
  const [localCompletedMap, setLocalCompletedMap] = useState({});
  const [localPriorityMap, setLocalPriorityMap] = useState({});
  const [editingId, setEditingId] = useState(null);
  const [editText, setEditText] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [toastMessage, setToastMessage] = useState('');

  const { data, loading, refetch } = useQuery(GET_TODOS, { variables: { userId: user.id } });
  const [createTodo] = useMutation(CREATE_TODO);
  const [deleteTodo] = useMutation(DELETE_TODO);

  const showToast = (msg) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(''), 3000);
  };

  const handleAddTodo = async (e) => {
    e.preventDefault();
    if (!taskText.trim() || isAdding) return;
    setIsAdding(true);
    try {
      const res = await createTodo({ variables: { userId: user.id, text: taskText } });
      if (res?.data?.createTodo?.id) {
        setLocalPriorityMap(prev => ({
          ...prev,
          [res.data.createTodo.id]: priority
        }));
      }
      setTaskText('');
      await refetch();
      showToast('Task added successfully!');
    } catch (err) {
      console.error(err);
    } finally {
      setIsAdding(false);
    }
  };

  const handleDeleteTodo = async (id) => {
    try {
      await deleteTodo({ variables: { id } });
      await refetch();
      showToast('Task deleted.');
    } catch (err) {
      console.error(err);
    }
  };

  const handleStartEdit = (task) => {
    setEditingId(task.id);
    setEditText(task.text);
  };

  const handleSaveEdit = (id) => {
    if (!editText.trim()) return;
    setEditingId(null);
    showToast('Task updated!');
  };

  const handleClearCompleted = async () => {
    const completedTasks = allTasks.filter(item => 
      localCompletedMap[item.id] !== undefined ? localCompletedMap[item.id] : item.completed
    );
    try {
      for (const task of completedTasks) {
        await deleteTodo({ variables: { id: task.id } });
      }
      await refetch();
      showToast('Cleared all completed tasks!');
    } catch (err) {
      console.error(err);
    }
  };

  const handleExportJSON = () => {
    const exportData = allTasks.map(item => ({
      id: item.id,
      text: item.text,
      completed: localCompletedMap[item.id] !== undefined ? localCompletedMap[item.id] : item.completed,
      priority: localPriorityMap[item.id] || 'Medium'
    }));

    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
    const downloadAnchor = document.createElement('a');
    downloadAnchor.setAttribute("href", dataStr);
    downloadAnchor.setAttribute("download", `tasks_backup_${user.email.split('@')[0]}.json`);
    document.body.appendChild(downloadAnchor);
    downloadAnchor.click();
    downloadAnchor.remove();
    showToast('Exported tasks to JSON!');
  };

  const toggleComplete = (id) => {
    setLocalCompletedMap(prev => ({
      ...prev,
      [id]: !prev[id]
    }));
  };

  const allTasks = data?.getTodos || [];

  const totalCount = allTasks.length;
  const completedCount = allTasks.filter(item => localCompletedMap[item.id] !== undefined ? localCompletedMap[item.id] : item.completed).length;
  const progressPercent = totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;

  // Filter Tasks
  let filteredTasks = allTasks.filter(item => {
    const isDone = localCompletedMap[item.id] !== undefined ? localCompletedMap[item.id] : item.completed;

    if (filterTab === 'active' && isDone) return false;
    if (filterTab === 'completed' && !isDone) return false;

    if (searchQuery.trim() && !item.text.toLowerCase().includes(searchQuery.toLowerCase())) {
      return false;
    }

    return true;
  });

  // Sort Tasks
  filteredTasks = [...filteredTasks].sort((a, b) => {
    if (sortBy === 'alphabetical') {
      return a.text.localeCompare(b.text);
    }
    if (sortBy === 'priority') {
      const priorityOrder = { High: 1, Medium: 2, Low: 3 };
      const prioA = priorityOrder[localPriorityMap[a.id] || 'Medium'];
      const prioB = priorityOrder[localPriorityMap[b.id] || 'Medium'];
      return prioA - prioB;
    }
    return 0; // Default
  });

  const getPriorityBadge = (p) => {
    switch (p) {
      case 'High':
        return <span className="text-[10px] font-bold uppercase tracking-wider text-rose-600 bg-rose-50 dark:bg-rose-950 dark:text-rose-400 px-2 py-0.5 rounded-md border border-rose-100 dark:border-rose-900">High</span>;
      case 'Low':
        return <span className="text-[10px] font-bold uppercase tracking-wider text-sky-600 bg-sky-50 dark:bg-sky-950 dark:text-sky-400 px-2 py-0.5 rounded-md border border-sky-100 dark:border-sky-900">Low</span>;
      default:
        return <span className="text-[10px] font-bold uppercase tracking-wider text-amber-600 bg-amber-50 dark:bg-amber-950 dark:text-amber-400 px-2 py-0.5 rounded-md border border-amber-100 dark:border-amber-900">Medium</span>;
    }
  };

  return (
    <div className={`min-h-screen py-10 px-4 relative transition-colors duration-200 ${darkMode ? 'bg-slate-900 text-slate-100' : 'bg-slate-50 text-slate-800'}`}>

      {/* Toast Notification Banner */}
      {toastMessage && (
        <div className="fixed bottom-6 right-6 z-50 bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 text-xs font-semibold px-4 py-3 rounded-xl shadow-xl flex items-center gap-2 animate-bounce">
          <span className="w-2 h-2 rounded-full bg-emerald-400 dark:bg-emerald-600"></span>
          <span>{toastMessage}</span>
        </div>
      )}

      <div className="max-w-2xl mx-auto space-y-6">

        {/* Header Bar */}
        <div className={`flex justify-between items-center p-6 rounded-2xl shadow-sm border transition-colors ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-100'}`}>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 text-white font-bold rounded-xl flex items-center justify-center text-lg shadow-sm">
              {user.email.charAt(0).toUpperCase()}
            </div>
            <div>
              <h1 className="text-lg font-bold leading-tight">Task Dashboard</h1>
              <p className="text-xs text-slate-400 mt-0.5">
                Connected as <span className="font-medium text-slate-600 dark:text-slate-300">{user.email}</span>
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setDarkMode(!darkMode)}
              className="p-2 rounded-xl text-xs font-semibold text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 transition"
              title="Toggle Theme"
            >
              {darkMode ? '☀️ Light' : '🌙 Dark'}
            </button>
            <button 
              onClick={onLogout}
              className="px-4 py-2 text-xs font-semibold text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-950/50 rounded-xl transition duration-150 border border-rose-100 dark:border-rose-900"
            >
              Logout
            </button>
          </div>
        </div>

        {/* Progress Overview Card */}
        {totalCount > 0 && (
          <div className={`p-5 rounded-2xl shadow-sm border transition-colors ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-100'}`}>
            <div className="flex justify-between items-center mb-2">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">Progress Overview</span>
              <span className="text-xs font-semibold text-emerald-600 dark:text-emerald-400">
                {completedCount} of {totalCount} completed ({progressPercent}%) {progressPercent === 100 ? '🎉' : ''}
              </span>
            </div>
            <div className="w-full bg-slate-100 dark:bg-slate-700 h-2.5 rounded-full overflow-hidden">
              <div 
                className={`h-full rounded-full transition-all duration-500 ${
                  progressPercent === 100 
                    ? 'bg-gradient-to-r from-emerald-500 to-teal-400 shadow-sm shadow-emerald-200' 
                    : 'bg-emerald-500'
                }`}
                style={{ width: `${progressPercent}%` }}
              ></div>
            </div>
          </div>
        )}

        {/* Add Task Input Form with Priority Selector */}
        <div className={`p-5 rounded-2xl shadow-sm border space-y-3 transition-colors ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-100'}`}>
          <form onSubmit={handleAddTodo} className="flex flex-col sm:flex-row gap-3">
            <input 
              type="text" 
              placeholder="What needs to be accomplished today?" 
              value={taskText}
              onChange={(e) => setTaskText(e.target.value)}
              className="flex-1 px-4 py-2.5 border rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 focus:outline-none text-sm transition dark:bg-slate-700 dark:border-slate-600 dark:text-white border-slate-200 text-slate-700"
            />
            <div className="flex gap-2">
              <select 
                value={priority}
                onChange={(e) => setPriority(e.target.value)}
                className="px-3 py-2.5 border rounded-xl text-xs font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer dark:bg-slate-700 dark:border-slate-600 dark:text-white border-slate-200 text-slate-600"
              >
                <option value="Low">Low Priority</option>
                <option value="Medium">Medium Priority</option>
                <option value="High">High Priority</option>
              </select>
              <button 
                type="submit"
                disabled={isAdding || !taskText.trim()}
                className="px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 text-white font-semibold rounded-xl text-sm transition duration-200 shadow-md shadow-indigo-100 dark:shadow-none disabled:opacity-50 whitespace-nowrap"
              >
                {isAdding ? 'Adding...' : 'Add Task'}
              </button>
            </div>
          </form>
        </div>

        {/* Tasks List Card with Search, Sorting, & Filters */}
        <div className={`rounded-2xl shadow-sm border overflow-hidden transition-colors ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-100'}`}>

          {/* Controls Header */}
          <div className={`p-5 border-b space-y-3 ${darkMode ? 'bg-slate-800/80 border-slate-700' : 'bg-slate-50/50 border-slate-100'}`}>
            <div className="flex flex-col sm:flex-row justify-between items-center gap-3">

              {/* Filter Tabs */}
              <div className={`flex p-1 rounded-xl text-xs font-medium w-full sm:w-auto ${darkMode ? 'bg-slate-700' : 'bg-slate-200/70'}`}>
                <button 
                  onClick={() => setFilterTab('all')}
                  className={`flex-1 sm:flex-none px-3 py-1.5 rounded-lg transition ${filterTab === 'all' ? (darkMode ? 'bg-slate-600 text-white shadow-xs font-semibold' : 'bg-white text-slate-800 shadow-xs font-semibold') : 'text-slate-400 hover:text-slate-200'}`}
                >
                  All ({allTasks.length})
                </button>
                <button 
                  onClick={() => setFilterTab('active')}
                  className={`flex-1 sm:flex-none px-3 py-1.5 rounded-lg transition ${filterTab === 'active' ? (darkMode ? 'bg-slate-600 text-white shadow-xs font-semibold' : 'bg-white text-slate-800 shadow-xs font-semibold') : 'text-slate-400 hover:text-slate-200'}`}
                >
                  Active
                </button>
                <button 
                  onClick={() => setFilterTab('completed')}
                  className={`flex-1 sm:flex-none px-3 py-1.5 rounded-lg transition ${filterTab === 'completed' ? (darkMode ? 'bg-slate-600 text-white shadow-xs font-semibold' : 'bg-white text-slate-800 shadow-xs font-semibold') : 'text-slate-400 hover:text-slate-200'}`}
                >
                  Completed
                </button>
              </div>

              {/* Instant Search & Sort Options */}
              <div className="flex gap-2 w-full sm:w-auto">
                <select
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value)}
                  className="px-3 py-1.5 text-xs border rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:bg-slate-700 dark:border-slate-600 dark:text-white border-slate-200 text-slate-700"
                >
                  <option value="default">Sort by: Default</option>
                  <option value="priority">Sort by: Priority</option>
                  <option value="alphabetical">Sort by: Name (A-Z)</option>
                </select>

                <div className="relative flex-1 sm:w-48">
                  <input 
                    type="text"
                    placeholder="Search tasks..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-8 pr-3 py-1.5 text-xs border rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:bg-slate-700 dark:border-slate-600 dark:text-white border-slate-200 text-slate-700"
                  />
                  <svg className="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                  </svg>
                </div>
              </div>

            </div>

            {/* Clear Completed & JSON Export Actions Bar */}
            <div className="flex justify-between items-center pt-2 text-xs">
              <button
                onClick={handleExportJSON}
                disabled={allTasks.length === 0}
                className="font-semibold text-indigo-600 dark:text-indigo-400 hover:underline disabled:opacity-40"
              >
                📥 Export JSON
              </button>

              {completedCount > 0 && (
                <button
                  onClick={handleClearCompleted}
                  className="font-semibold text-slate-500 dark:text-slate-400 hover:text-rose-600 dark:hover:text-rose-400 transition"
                >
                  Clear Completed ({completedCount})
                </button>
              )}
            </div>
          </div>

          {/* List Content */}
          {loading ? (
            <div className="p-8 text-center text-slate-400 text-sm flex items-center justify-center gap-2">
              <div className="w-4 h-4 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
              <span>Loading tasks from server...</span>
            </div>
          ) : filteredTasks.length === 0 ? (
            <div className="p-12 text-center">
              <div className="w-12 h-12 bg-slate-100 dark:bg-slate-700 text-slate-400 rounded-full flex items-center justify-center mx-auto mb-3">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 002 2h2a2 2 0 002-2" />
                </svg>
              </div>
              <p className="font-medium text-sm">No tasks found</p>
              <p className="text-slate-400 text-xs mt-1">Try adjusting your search, filters, or add a new task!</p>
            </div>
          ) : (
            <ul className={`divide-y ${darkMode ? 'divide-slate-700' : 'divide-slate-100'}`}>
              {filteredTasks.map((item) => {
                const isDone = localCompletedMap[item.id] !== undefined ? localCompletedMap[item.id] : item.completed;
                const taskPriority = localPriorityMap[item.id] || 'Medium';
                const isEditingThis = editingId === item.id;

                return (
                  <li key={item.id} className={`px-6 py-4 flex items-center justify-between transition group ${darkMode ? 'hover:bg-slate-700/50' : 'hover:bg-slate-50/60'}`}>
                    <div className="flex items-center gap-3.5 flex-1 pr-4">
                      <input 
                        type="checkbox"
                        checked={isDone}
                        onChange={() => toggleComplete(item.id)}
                        className="w-4 h-4 text-indigo-600 rounded border-slate-300 focus:ring-indigo-500 cursor-pointer shrink-0"
                      />

                      {isEditingThis ? (
                        <div className="flex items-center gap-2 flex-1">
                          <input 
                            type="text"
                            value={editText}
                            onChange={(e) => setEditText(e.target.value)}
                            className="px-2 py-1 text-xs border border-indigo-300 rounded-md focus:outline-none focus:ring-1 focus:ring-indigo-500 flex-1 dark:bg-slate-700 dark:text-white"
                          />
                          <button 
                            onClick={() => handleSaveEdit(item.id)}
                            className="text-xs font-semibold text-emerald-600 dark:text-emerald-400 px-2 py-1"
                          >
                            Save
                          </button>
                        </div>
                      ) : (
                        <div className="flex items-center gap-2 flex-1">
                          <span 
                            onDoubleClick={() => handleStartEdit(item)}
                            className={`text-sm font-medium transition cursor-pointer ${isDone ? 'line-through text-slate-400 dark:text-slate-500' : ''}`}
                          >
                            {item.text}
                          </span>
                          {getPriorityBadge(taskPriority)}
                        </div>
                      )}
                    </div>

                    <div className="flex items-center gap-1">
                      {!isEditingThis && (
                        <button 
                          onClick={() => handleStartEdit(item)}
                          className="text-xs font-medium text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-400 px-2 py-1 rounded transition"
                        >
                          Edit
                        </button>
                      )}
                      <button 
                        onClick={() => handleDeleteTodo(item.id)}
                        className="text-xs font-semibold text-rose-500 hover:text-rose-700 dark:hover:text-rose-400 px-3 py-1.5 rounded-lg bg-rose-50/50 dark:bg-rose-950/40 hover:bg-rose-100 dark:hover:bg-rose-900/60 transition duration-150"
                      >
                        Delete
                      </button>
                    </div>
                  </li>
                );
              })}
            </ul>
          )}
        </div>

      </div>
    </div>
  );
}
